var n=`1192-kakik`;var t=`world-1192`;var a=`GT`;var s=`central-america-caribbean`;var r=4;var o=137;var m={en:`Kak'ik`,ua:`Как'ік`};var l={en:`Kak'ik is a dish from Guatemala prepared with tomato, yellow onion, garlic, achiote paste. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Как'ік, страва кухні країни Гватемала, яку готують із таких продуктів: помідор, жовта цибуля, часник, паста ачіоте. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Toast these ingredients over medium heat for about 5 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 5 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:5,i:[[`allspice-berries`,8,`pcs`],[`black-peppercorn`,8,`pcs`],[`ground-cloves`,4,`pcs`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`tomato`,300,`g`],[`yellow-onion`,180,`g`],[`garlic`,5,`clove`],[`achiote-paste`,30,`g`],[`cilantro`,30,`g`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 95 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 95 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:95,i:[[`turkey-drumstick`,950,`g`],[`water`,1350,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`serrano-pepper`,2,`pcs`]]}];var d={slug:n,id:t,country:`GT`,region:s,servings:4,minutes:137,title:m,text:l,steps:g};export{a as country,d as default,t as id,o as minutes,s as region,r as servings,n as slug,g as steps,l as text,m as title};